  ('d47c946b-9177-4811-8d22-dd3f7b25c4bb', '197a4489-99b8-400f-85f1-70158c35f3f9', NULL, 'out', 'wamid.demo.out.d47c946b', 'text', 'Got it, Marco — 2 min 48 s and 2 photos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'read', NULL, '2026-10-09T22:38:00.000Z'),
  ('b1871246-f351-452c-8039-9f9ac7305876', '197a4489-99b8-400f-85f1-70158c35f3f9', NULL, 'out', 'wamid.demo.out.b1871246', 'interactive', 'Quick check: you said ''the Delta guys'' were on Level 2. How many, and for how long?', '{"buttons":[{"id":"q:27d35235-2374-412b-86f7-9b39502bdfe5:0","title":"4 · full day"},{"id":"q:27d35235-2374-412b-86f7-9b39502bdfe5:1","title":"5 · full day"},{"id":"q:27d35235-2374-412b-86f7-9b39502bdfe5:other","title":"Other…"}]}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'read', NULL, '2026-10-09T22:40:00.000Z'),
  ('0dfc3710-0825-463a-8775-6a14ac466ee0', '197a4489-99b8-400f-85f1-70158c35f3f9', NULL, 'in', 'wamid.demo.hero.answer', 'interactive', '5 · full day', '{"button_reply":{"id":"q:27d35235-2374-412b-86f7-9b39502bdfe5:1","title":"5 · full day"}}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'received', NULL, '2026-10-09T22:41:00.000Z'),
  ('593992f1-446d-4d17-8d3c-20ddf7b2e9e1', '197a4489-99b8-400f-85f1-70158c35f3f9', NULL, 'out', 'wamid.demo.out.593992f1', 'text', 'Thanks — Delta Mechanical: 5 workers × 8 h = 40 h.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'read', NULL, '2026-10-09T22:41:00.000Z'),
  ('3f8d6395-18ba-4793-826c-6d81f0cafa65', '197a4489-99b8-400f-85f1-70158c35f3f9', NULL, 'out', 'wamid.demo.out.3f8d6395', 'interactive', 'DRAFT · FRI OCT 9
insert into transcripts (id, message_id, language, text, segments, model, created_at, upload_id, call_id) values
  ('bb3d94df-3301-4b31-8fe5-7c930b20608f', '1a4585bd-f630-4f17-8679-2191100d816d', 'es+en', 'Okay, Friday, Riverside Block B. Big day on four. We poured the deck on four, like sixty-eight yards, finished about two thirty. Apex had six guys on it. BrightLine, five electricians on three doing the rough-in, I''d say sixty percent. The Delta guys were on two running duct on the east wing. Llovió desde las siete hasta las diez y media, no pudimos hacer block afuera, los de masonry se metieron adentro, perdimos como tres horas y media. Ironclad dropped two loads of rebar around one, three of their guys stayed to tie. Our guys, four of us, cleaning and layout for five. Toolbox talk this morning on wet weather access, no incidents. Monday we need the pump at seven for the level five deck. Ah, y el inspector de la ciudad vino a ver el colado, todo bien, firmó. One more thing, the west stair, the handrail is still missing on three, I put a barricade, we need the steel guys next week. Photos coming, one of the pour and one of the rain this morning so you have it for the record. That''s it, that''s Friday. Have a good weekend.', '[{"start":0,"end":8.2,"text":"Okay, Friday, Riverside Block B. Big day on four."},{"start":8.2,"end":18.9,"text":"We poured the deck on four, like sixty-eight yards, finished about two thirty. Apex had six guys on it."},{"start":18.9,"end":30.5,"text":"BrightLine, five electricians on three doing the rough-in, I''d say sixty percent."},{"start":30.5,"end":41,"text":"The Delta guys were on two running duct on the east wing."},{"start":41,"end":52.3,"text":"Llovió desde las siete hasta las diez y media, no pudimos hacer block afuera, los de masonry se metieron adentro, perdimos como tres horas y media."},{"start":52.3,"end":63,"text":"Ironclad dropped two loads of rebar around one, three of their guys stayed to tie."},{"start":63,"end":74.4,"text":"Our guys, four of us, cleaning and layout for five."},{"start":74.4,"end":86,"text":"Toolbox talk this morning on wet weather access, no incidents."},{"start":86,"end":98.5,"text":"Monday we need the pump at seven for the level five deck."},{"start":98.5,"end":112,"text":"Ah, y el inspector de la ciudad vino a ver el colado, todo bien, firmó."},{"start":112,"end":128,"text":"One more thing, the west stair, the handrail is still missing on three, I put a barricade, we need the steel guys next week."},{"start":128,"end":146,"text":"Photos coming, one of the pour and one of the rain this morning so you have it for the record."},{"start":146,"end":168,"text":"That''s it, that''s Friday. Have a good weekend."}]'::jsonb, 'whisper-1', '2026-10-09T22:38:00.000Z', NULL, NULL),
  ('e658a550-1217-4ea6-89a5-a584b0e68c20', 'cec5ca3f-3d1a-4345-8f17-1ac3372dee8f', 'en', 'Hey, this is Luis, covering Elm St. today for Priya. We framed units one through four, six guys, no rain. I''ll send photos.', '[{"start":0,"end":12.5,"text":"Hey, this is Luis, covering Elm St. today for Priya."},{"start":12.5,"end":28,"text":"We framed units one through four, six guys, no rain."},{"start":28,"end":41,"text":"I''ll send photos."}]'::jsonb, 'whisper-1', '2026-10-09T22:53:00.000Z', NULL, NULL);
